sksl:
uniform shader image;
uniform float2 size;
uniform float time;
layout(color) uniform half4 shadows;
layout(color) uniform half4 midtones;
layout(color) uniform half4 highlights;
uniform float amount;
half luma(half3 c) {
    return dot(c, half3(0.2126, 0.7152, 0.0722));
}
half3 applyBalance(half3 rgb, half3 balance, float amt) {
    half l = luma(rgb);
    float w = (l < 0.5) ? (1.0 - l * 2.0) : 0.0;
    float s = (l > 0.5) ? (l * 2.0 - 1.0) : 0.0;
    half3 b = mix(half3(0.5), balance, amt);
    half3 r = mix(b, balance, s);
    return mix(rgb, r, amt);
}
half4 main(float2 coord) {
    half4 c = image.eval(coord);
    half a = c.a;
    if (a < 0.001) return c;
    half3 rgb = c.rgb / a;
    half l = luma(rgb);
    half3 bc;
    if (l < 0.33) {
        bc = shadows.rgb;
    } else if (l < 0.66) {
        bc = midtones.rgb;
    } else {
        bc = highlights.rgb;
    }
    half3 res = applyBalance(rgb, bc, amount);
    return half4(res * a, a);
}
